def encode_decode_cyclic(s: str, mode: str = 'encode') -> str:
    """
    Encodes or decodes a string by cycling groups of three characters.

    Args:
        s (str): The input string.
        mode (str, optional): 'encode' or 'decode'. Defaults to 'encode'.

    Returns:
        str: The encoded or decoded string.

    Raises:
        ValueError: If the mode is not 'encode' or 'decode'.
    """
    if mode not in ['encode', 'decode']:
        raise ValueError("Invalid mode. Use 'encode' or 'decode'.")

    chunks = [s[(3 * i):min((3 * i + 3), len(s))] for i in range((len(s) + 2) // 3)]
    if mode == 'encode':
        return ''.join(chunk[1:] + chunk[0] if len(chunk) == 3 else chunk for chunk in chunks)
    elif mode == 'decode':
        return ''.join(chunk[-1] + chunk[:-1] for chunk in chunks)

